<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pdo=db();$bid=branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM cash_movements WHERE id=? AND branch_id=?')->execute([(int)$_POST['delete'],$bid]);flash('success','Catatan keuangan dihapus.');}else{$type=$_POST['type']??'';$amount=(float)($_POST['amount']??0);if(!in_array($type,['income','expense'],true)||$amount<=0){flash('error','Jenis dan nominal belum valid.');}else{$pdo->prepare('INSERT INTO cash_movements(branch_id,user_id,type,category,amount,description,movement_date) VALUES(?,?,?,?,?,?,?)')->execute([$bid,user()['id'],$type,trim($_POST['category']),$amount,trim($_POST['description']),$_POST['movement_date']]);flash('success','Catatan keuangan disimpan.');}}redirect('/owner/keuangan.php');}
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=$pdo->prepare('SELECT c.*,u.name recorder FROM cash_movements c JOIN users u ON u.id=c.user_id WHERE c.branch_id=? AND c.movement_date BETWEEN ? AND ? ORDER BY c.movement_date DESC,c.id DESC');$s->execute([$bid,$from,$to]);$rows=$s->fetchAll();$income=0;$expense=0;foreach($rows as $r){if($r['type']==='income')$income+=(float)$r['amount'];else $expense+=(float)$r['amount'];}$pageTitle='Pemasukan & Pengeluaran';$active='keuangan';include __DIR__.'/../includes/header.php';?>
<div class="grid two-col"><section class="card"><h2>Catat arus kas</h2><form method="post" class="form-grid" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Jenis<select name="type"><option value="expense">Pengeluaran</option><option value="income">Pemasukan lain</option></select></label><label>Tanggal<input type="date" name="movement_date" value="<?=date('Y-m-d')?>" required></label><label>Kategori<input name="category" required placeholder="Contoh: Bahan baku"></label><label>Nominal<input type="number" name="amount" min="1" required></label><label class="field full">Keterangan<input name="description" required placeholder="Jelaskan transaksi"></label><button class="btn primary">Simpan catatan</button></form></section><section class="card"><h2>Ringkasan periode</h2><div class="summary-row"><span>Pemasukan lain</span><strong><?=rupiah($income)?></strong></div><div class="summary-row"><span>Pengeluaran</span><strong><?=rupiah($expense)?></strong></div><div class="summary-row total"><span>Arus kas bersih</span><strong><?=rupiah($income-$expense)?></strong></div><small class="muted">Penjualan dihitung otomatis dan tidak perlu dicatat kembali di sini.</small></section></div>
<section class="card" style="margin-top:18px"><form class="filter-row"><label>Dari<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn soft">Tampilkan</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Keterangan</th><th>Nominal</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y',strtotime($r['movement_date']))?></td><td><span class="badge <?=$r['type']==='expense'?'warn':''?>"><?=$r['type']==='income'?'Pemasukan':'Pengeluaran'?></span></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td><?=rupiah($r['amount'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="btn danger sm" name="delete" value="<?=$r['id']?>">Hapus</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state">Belum ada catatan keuangan.</div><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>
